mapper.update:
UPDATE biz_product_batch
SET locked_quantity = locked_quantity + #{lockAmount},
    modified_time = NOW()
WHERE id = #{id}
  AND status = 0
  AND (quantity - locked_quantity) >= #{lockAmount}

UPDATE biz_product_batch
SET locked_quantity = locked_quantity - #{unlockAmount},
    modified_time = NOW()
WHERE id = #{id}
  AND locked_quantity >= #{unlockAmount}

UPDATE biz_product_batch
SET quantity = quantity - #{deductAmount},
    locked_quantity = locked_quantity - #{deductAmount},
    modified_time = NOW()
WHERE id = #{id}
  AND quantity >= #{deductAmount}
  AND locked_quantity >= #{deductAmount}
